// ==UserScript==
// @author       Journey Over
// @exclude      *
// ==UserLibrary==
// @name         @journeyover/anilist
// @description  AniList GraphQL API client
// @license      MIT
// @version      1.1.0
// @homepageURL  https://github.com/StylusThemes/Userscripts
// ==/UserLibrary==
// @connect      graphql.anilist.co
// @grant        GM_xmlhttpRequest
// ==/UserScript==

this.AniList=class{query(query,variables={}){if(!query)throw new Error('A GraphQL query is required');return new Promise((resolve,reject)=>{GM_xmlhttpRequest({method:'POST',url:'https://graphql.anilist.co',headers:{'Content-Type':'application/json',Accept:'application/json'},data:JSON.stringify({query:query,variables:variables}),timeout:15e3,onload:response=>{if(response.status!==200){}if(response.status===200){try{const data=JSON.parse(response.responseText);resolve(data)}catch{reject(new Error('Failed to parse AniList response'))}}else{reject(new Error(`AniList API error: ${response.status}`))}},onerror:()=>{reject(new Error('An error occurs while processing the request'))},ontimeout:()=>{reject(new Error('Request times out'))}})})}async hasDub(anilistId,language){if(!anilistId)throw new Error('An AniList ID is required');if(!language)throw new Error('A language is required');const query=`\n      query($id: Int, $language: StaffLanguage) {\n        Media(id: $id, type: ANIME) {\n          characters(role: MAIN, sort: ROLE) {\n            edges {\n              voiceActors(language: $language) { language }\n            }\n          }\n        }\n      }\n    `;const response=await this.query(query,{id:Number(anilistId),language:language});const edges=response?.data?.Media?.characters?.edges;if(!Array.isArray(edges))throw new Error('Unexpected AniList response structure');return edges.some(edge=>edge.voiceActors?.length>0)}};
